def wrap(name,h,kicker,body,footer='INTERIOR DESIGN & FIT-OUT'):
 s=f'''<!doctype html><html lang="ar"><meta charset="utf-8"><title>VILL {name} — PREVIS</title><style>{variables}{css}</style><main class="theme-dark" style="height:{h}px"><img class="logo" src="../../../../brands/vill-studio/assets/final/Logo.png" alt="Official VILL logo"><div class="kicker">{kicker}</div>{body}<div class="foot"><span>{footer}</span><span>VILL / CONCEPT</span></div></main></html>''';
 if name=='single-post':
  s=s.replace('color:var(--background)', 'color:var(--palette-navy)')
